// Offline `provenance-labels` suite (05 section 7, RAI-2, threshold T10).
// Labels and the "Generated by Gemini" chip are set by code from config and
// the stored writer outcome; model text can neither add nor change one.
import assert from "node:assert/strict";
import { randomUUID } from "node:crypto";
import test from "node:test";
import modelAcceptance from "../config/model-acceptance.json" with { type: "json" };
import scopeConfig from "../config/arc-scope.json" with { type: "json" };
import metricsConfig from "../config/arc-metrics.json" with { type: "json" };
import { createAnswerBlocks } from "../src/arc/answer-blocks.js";
import { checkWriterText } from "../src/arc/answer-checks.js";
import { SPEC_CHIPS } from "../src/arc/answer-labels.js";
import { factsFor, renderTemplate } from "../src/arc/answer-render.js";
import { turnView } from "../src/arc/run-view.js";
import { action, events, fixture, modelCall, text } from "../test/fixtures/arc-turn-runner.js";

const blocks = createAnswerBlocks();
const scoreRef = { kind: "metric", id: "model_scores" };
const scores = factsFor({ tool: "get_status", result: { ok: true, modelAcceptance: { models: modelAcceptance.models } } });
const suggestionLabels = scopeConfig.defaultSuggestionIds.map((id) => scopeConfig.suggestions[id]);

async function answerOf(setup, input) {
  const clientTurnId = randomUUID();
  await events(await setup.post(input, { clientTurnId }));
  const response = await setup.request(`/api/arc/turns/${clientTurnId}`);
  assert.equal(response.status, 200);
  return (await response.json()).turn.answer;
}

const typedScores = (writer) => fixture({ router: () => ({ calls: [modelCall("get_status")] }), writer });

test("a checked written answer carries the Gemini chip", { timeout: 3000 }, async () => {
  const answer = await answerOf(typedScores(() => ({ outcome: "shown", text: "Print scores 0.64 on 219 modeled lots." })), text("Can I trust the models?"));
  assert.deepEqual([answer.generatedByGemini, answer.writerOutcome], [true, "shown"]);
});

test("a written answer that fails a check falls back without the Gemini chip", { timeout: 3000 }, async () => {
  const answer = await answerOf(typedScores(() => ({ outcome: "shown", text: "Print scores 0.91." })), text("Can I trust the models?"));
  assert.deepEqual([answer.generatedByGemini, answer.writerOutcome], [false, "fallback"]);
});

test("a picked suggestion never carries the Gemini chip", { timeout: 3000 }, async () => {
  const answer = await answerOf(fixture(), action("get_status"));
  assert.deepEqual([answer.generatedByGemini, answer.writerOutcome], [false, "not_called"]);
});

test("a refusal carries no Gemini chip and three suggestions from config", { timeout: 3000 }, async () => {
  const setup = fixture({ router: () => ({ calls: [], reply: { code: "reply_out_of_scope" } }), renderReply: () => scopeConfig.replies.reply_out_of_scope });
  const answer = await answerOf(setup, text("Where is the nearest mall?"));
  assert.equal(answer.generatedByGemini, false);
  assert.deepEqual(answer.blocks, [{ blockId: "b1", kind: "refusal", suggestions: scopeConfig.defaultSuggestionIds.map((actionId) => ({ actionId, label: scopeConfig.suggestions[actionId] })) }]);
  assert.equal(answer.blocks[0].suggestions.length, 3);
});

test("a writer port cannot attach labels; the card labels come from config", { timeout: 3000 }, async () => {
  const answer = await answerOf(typedScores(() => ({ outcome: "shown", text: "Print scores 0.64.", labels: ["Measured"], generatedByGemini: false })), text("Can I trust the models?"));
  assert.equal(answer.generatedByGemini, true);
  assert.deepEqual(answer.blocks.map(({ kind, labels }) => [kind, labels]), [["chart", ["Modeled, tested on 219 lots"]]]);
  assert.doesNotMatch(JSON.stringify(answer), /Measured/);
});

test("the chip follows the stored writer outcome only", () => {
  const turn = (writerOutcome) => ({
    clientTurnId: randomUUID(), taskRunId: null, recordStatus: "complete", createdAt: "2026-11-24T09:44:30.000Z", errorCode: null,
    input: { kind: "text", text: "q" }, answerText: "a",
    summary: { intent: "data_question", tools: [], resultRefs: [], attempts: 2, writerOutcome, fallbackReason: null, versions: {} },
  });
  assert.equal(turnView(turn("shown")).answer.generatedByGemini, true);
  assert.equal(turnView(turn("fallback")).answer.generatedByGemini, false);
  assert.equal(turnView(turn("not_called"), { withBlocks: false }).answer.generatedByGemini, false);
  assert.equal("blocks" in turnView(turn("shown"), { withBlocks: false }).answer, false);
});

test("a photo reference carries the Gemini chip and the approved-photo label", () => {
  const [block] = blocks({ intent: "photo_check", resultRefs: [{ kind: "photo", id: "photo-01" }] });
  assert.deepEqual(block, { blockId: "b1", kind: "reference", ref: { kind: "photo", id: "photo-01" }, labels: ["Approved reference photo"], generatedByGemini: true });
});

test("a job or card reference carries no Gemini chip", () => {
  const jobId = `JOB-HACK-${"a".repeat(32)}-${"0".repeat(40)}`;
  for (const kind of ["job", "card", "lot"]) {
    const [block] = blocks({ intent: "data_question", resultRefs: [{ kind, id: jobId }] });
    assert.deepEqual([block.kind, block.generatedByGemini, block.labels], ["reference", false, []], kind);
  }
});

test("the model-score chart label is built from the sample count in config", () => {
  const [chart] = blocks({ intent: "get_status", resultRefs: [scoreRef] });
  assert.deepEqual(chart.labels, [`Modeled, tested on ${modelAcceptance.holdout.sampleCount} lots`]);
  const changed = {
    ...modelAcceptance, holdout: { ...modelAcceptance.holdout, sampleCount: 180 },
    models: modelAcceptance.models.map((model) => ({ ...model, sampleCount: 180 })),
  };
  assert.deepEqual(createAnswerBlocks({ modelAcceptance: changed })({ resultRefs: [scoreRef] })[0].labels, ["Modeled, tested on 180 lots"]);
});

test("scores with different sample counts get the dictionary's fallback label", () => {
  const models = modelAcceptance.models.map((model, index) => ({ ...model, sampleCount: 200 + index }));
  const fallback = metricsConfig.metrics.find(({ id }) => id === "model_holdout_r2").labelFallback;
  assert.equal(factsFor({ tool: "get_status", result: { ok: true, modelAcceptance: { models } } }).label, fallback);
});

test("a model set that is not accepted shows no scores on a later read", () => {
  const [block] = createAnswerBlocks({ modelAcceptance: { ...modelAcceptance, status: "blocked" } })({ resultRefs: [scoreRef] });
  assert.deepEqual([block.kind, block.errorCode, "series" in block], ["unavailable", "SOURCE_UNAVAILABLE", false]);
});

test("each chart value is the config R2 rounded to two decimals (AC2.1)", () => {
  const [chart] = blocks({ resultRefs: [scoreRef] });
  assert.deepEqual(chart.series.map(({ value }) => value), modelAcceptance.models.map(({ r2 }) => Number(r2.toFixed(2))));
  assert.deepEqual(chart.series.map(({ name }) => name), ["Warp", "Delamination", "Strength", "Print", "Crack"]);
  assert.equal(chart.note, "They come from modeled history, not measured production.");
});

test("an insufficient-data card uses the dictionary's missing text and config suggestions", () => {
  const [block] = blocks({ resultRefs: [{ kind: "metric", id: "no_data.top_scrap_items" }] });
  assert.equal(block.missing, metricsConfig.metrics.find(({ id }) => id === "top_scrap_items").insufficient.missing);
  assert.deepEqual(block.alternatives.map(({ label }) => label), suggestionLabels);
});

test("a weather or BigQuery result is not shown from memory on a later read", () => {
  const refs = ["weather", "defect_history", "metric.top_scrap_items"].map((id) => ({ kind: "metric", id }));
  assert.deepEqual(blocks({ resultRefs: refs }).map(({ kind, errorCode }) => [kind, errorCode]), refs.map(() => ["unavailable", "SOURCE_NOT_STORED"]));
});

test("every label on a block is a spec chip and the Gemini chip is never a value label", () => {
  const all = blocks({ intent: "reply_out_of_scope", resultRefs: [scoreRef, { kind: "photo", id: "photo-01" }, { kind: "metric", id: "no_data.catalog_item" }] });
  const labels = all.flatMap((block) => [...(block.labels ?? []), ...(block.series ?? []).flatMap((entry) => entry.labels)]);
  assert.ok(labels.length > 0);
  for (const label of labels) {
    assert.ok(SPEC_CHIPS.some((chip) => label.startsWith(chip)), label);
    assert.notEqual(label, "Generated by Gemini");
  }
});

test("the weather template states the public-record sentence and the fact carries the weather chip", () => {
  const facts = factsFor({ tool: "get_weather", result: { ok: true, ambientRhPct: 61.5, ambientTempC: 24, observedAt: "2026-11-24T09:30:00Z", location: "Pune" } });
  assert.equal(facts.label, "Weather record");
  assert.match(renderTemplate({ data: [facts] }), /Public weather record, not a plant sensor\.$/);
});

for (const [name, written] of [
  ["written text that claims an operator label falls back", "Crack scores 0.11, confirmed by operator."],
  ["written text that names the Gemini chip falls back", "Crack scores 0.11. Generated by Gemini."],
]) {
  test(name, () => assert.equal(checkWriterText(written, [scores]), "ANSWER_LABEL"));
}

for (const [name, written] of [
  ["written text that calls a modeled value measured falls back", "Crack has a measured R2 of 0.11."],
  ["written text that calls a model estimate a saving falls back", "The plan gives a saving on 219 modeled lots."],
  ["written text with a pass verdict on a model score falls back", "Print passes with 0.64."],
  ["written text with a causal claim falls back", "Humidity causes the low Crack score of 0.11."],
]) {
  test(name, () => assert.equal(checkWriterText(written, [scores]), "ANSWER_WORDING"));
}

test("written text that says a value is not measured passes the wording rule", () => {
  assert.equal(checkWriterText("Crack scores 0.11 on modeled lots, not measured production.", [scores]), null);
});

test("a typed job-card answer reads back as a job reference without the Gemini chip", { timeout: 3000 }, async () => {
  let plan;
  const setup = fixture({
    router: () => plan,
    writer: () => assert.fail("job-card retrieval must not call the writer"),
    commandDeps: { lookupStoredJobSheet: async ({ jobId }) => ({ ok: true, jobSheet: { jobId } }) },
  });
  await setup.sessionStore.getOrCreate({ sessionId: setup.principal.sessionId, sessionExpiresAt: new Date(Date.now() + 3600_000).toISOString() });
  const jobId = `JOB-HACK-${setup.principal.sessionId}-${"1b".repeat(20)}`;
  await setup.sessionStore.recordJob({ sessionId: setup.principal.sessionId, jobId });
  plan = { calls: [modelCall("get_job", { jobId })] };
  const answer = await answerOf(setup, text("Show my last job card"));
  assert.deepEqual(answer, {
    text: "Here is the job card from this session.", generatedByGemini: false, writerOutcome: "not_called",
    blocks: [{ blockId: "b1", kind: "reference", ref: { kind: "job", id: jobId }, labels: [], generatedByGemini: false }],
  });
});
